def count_nums(arr):
    def get_digit_sum(n):
        """Helper function to calculate the sum of digits"""
        if n == 0:
            return 0
        else:
            return (n % 10) + get_digit_sum(n // 10)
    count = 0
    for num in arr:
        digit_sum = get_digit_sum(num)
        if digit_sum > 0:
            count += 1
    return count
```
